#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *data;
    size_t size, cap;
} Stack;

static int push(Stack *s, int v) {
    if (s->size == s->cap) {
        size_t ncap = s->cap ? s->cap * 2 : 2;
        int *nd = realloc(s->data, ncap * sizeof *nd);
        if (!nd) return 0;
