Show a simple hash map with collision handling, so I understand how dict works.

```python
class HashMap:
    def __init__(self, buckets=8):
        self.buckets = [[] for _ in range(buckets)]
    def _bucket(self, key):
        return self.buckets[hash(key) % len(self.buckets)]
    def put(self, key, value):
        b = self._bucket(key)
        for pair in b:
            if pair[0] == key:
                pair[1] = value
                return
        b.append([key, value])
    def get(self, key, default=None):
        for k, v in self._bucket(key):
            if k == key:
                return v
        return default

