```python
class Trie:
    def __init__(self):
        self.root = {}
    def insert(self, word):
        node = self.root
        for ch in word:
            node = node.setdefault(ch, {})
        node["$"] = True
    def _find(self, prefix):
        node = self.root
        for ch in prefix:
            if ch not in node:
                return None
            node = node[ch]
        return node
    def contains(self, word):
        n = self._find(word)
        return bool(n and "$" in n)
    def with_prefix(self, prefix):
        out = []
        def walk(node, path):
            if "$" in node:
                out.append(prefix + path)
            for ch in sorted(k for k in node if k != "$"):
                walk(node[ch], path + ch)
        n = self._find(prefix)
        if n:
            walk(n, "")
        return out

