How do I check if a string is a valid permutation of another one efficiently?

```python
from collections import Counter

def is_permutation(a, b):
    return len(a) == len(b) and Counter(a) == Counter(b)

def find_anagram_windows(text, pattern):
    need, k = Counter(pattern), len(pattern)
    window = Counter(text[:k])
    hits = [0] if window == need else []
    for i in range(k, len(text)):
        window[text[i]] += 1
        old = text[i - k]
        window[old] -= 1
        if window[old] == 0:
            del window[old]
        if window == need:
            hits.append(i - k + 1)
    return hits

