Here's the Java equivalent:

```java
static int[] bubbleSort(int[] input) {
    int[] arr = input.clone();
    for (int end = arr.length - 1; end > 0; end--) {
        boolean swapped = false;
        for (int i = 0; i < end; i++) {
            if (arr[i] > arr[i + 1]) {
                int t = arr[i];
                arr[i] = arr[i + 1];
                arr[i + 1] = t;
                swapped = true;
            }
        }
        if (!swapped) break;
    }
    return arr;
}
